import fitz, glob, os, re

# Load all text from shipped standards
standards_dir = '/filesystem/dc_structural__eor_revision__blind/project/standards'
pdf_texts = {}
for p in sorted(glob.glob(f'{standards_dir}/*.pdf')):
    doc = fitz.open(p)
    full_text = []
    for page in doc:
        full_text.append(page.get_text())
    pdf_texts[os.path.basename(p)] = '\n'.join(full_text)

def tokenize_words(text):
    # a word is a run of two or more letters
    return re.findall(r'[a-zA-Z]{2,}', text.lower())

standards_word_sets = {}
for fname, txt in pdf_texts.items():
    words = tokenize_words(txt)
    # create 16-grams
    grams_16 = set()
    for i in range(len(words) - 15):
        grams_16.add(tuple(words[i:i+16]))
    standards_word_sets[fname] = grams_16
    print(f'{fname}: {len(words)} words, {len(grams_16)} 16-grams')

# Check deliverables
for deliv in ['continuation_sheet.md', 'design_basis.md']:
    p = f'/tmp/submission_staging/{deliv}'
    content = open(p).read()
    # Strip json code block from design_basis.md for narrative licensing check
    content_narrative = re.sub(r'```json.*?```', '', content, flags=re.DOTALL)
    words = tokenize_words(content_narrative)

    matches_found = []
    for i in range(len(words) - 15):
        gram = tuple(words[i:i+16])
        for fname, s_grams in standards_word_sets.items():
            if gram in s_grams:
                matches_found.append((fname, ' '.join(gram)))

    if matches_found:
        print(f'WARNING: {deliv} has {len(matches_found)} verbatim 16-word runs!')
        for mf in matches_found[:5]:
            print('  ', mf)
    else:
        print(f'PASS: {deliv} has 0 verbatim 16-word runs!')
